```csharp
using System.Text;
using System.Text.RegularExpressions;
using System.Globalization;

public static class Slug
{
    public static string Make(string title)
    {
        if (title == null)
        {
            throw new ArgumentNullException(nameof(title));
        }

        // Descomponer los diacríticos para que las tildes pasen a ser marcas independientes
        var decomposed = title.Normalize(NormalizationForm.FormD);

        // Eliminar las marcas de acento (á -> a, ñ -> n, ü -> u)
        var withoutAccents = new StringBuilder();
        foreach (var c in decomposed)
        {
            if (CharUnicodeInfo.GetUnicodeCategory(c) == UnicodeCategory.NonSpacingMark)
            {
                continue;
            }
            withoutAccents.Append(c);
        }

        // Volver a componer y pasar a minúsculas
        var cleaned = withoutAccents.ToString().Normalize(NormalizationForm.FormC).ToLowerInvariant();

        // Toda secuencia de caracteres no a-z/0-9 se convierte en un único guion
        var result = Regex.Replace(cleaned, "[^a-z0-9]+", "-");

        // Sin guiones al principio ni al final
        return result.Trim('-');
    }
}
```

