using System;
using System.Collections.Generic;

public static class Csv
{
    public static List<string> ParseLine(string line)
    {
        var result = new List<string>();
        if (line == null)
            throw new ArgumentNullException(nameof(line));

        var chars = line.ToCharArray();
        int n = chars.Length;
        int i = 0;

        while (i < n)
        {
            // Skip... actually we don't skip spaces. But we need to handle empty fields.
            // An empty field occurs between two commas.

            // Check if current char is a quote
            if (chars[i] == '"')
            {
                // Quoted field
                var sb = new StringBuilder();
                i++; // skip opening quote
                while (i < n)
                {
                    if (chars[i] == '"')
                    {
                        // Check if it's an escaped quote or closing quote
                        if (i + 1 < n && chars[i + 1] == '"')
                        {
                            sb.Append('"');
                            i += 2;
                        }
                        else
                        {
                            // closing quote
                            i++;
                            break;
                        }
                    }
                    else
                    {
                        sb.Append(chars[i]);
                        i++;
                    }
                }
                // After closing quote, we expect a comma or end of line
                if (i < n && chars[i] != ',')
                {
                    throw new FormatException("Expected comma or end of line after quoted field.");
                }
                result.Add(sb.ToString());
            }
            else
