def merge_intervals(intervals: list[tuple[int, int]]) -> list[tuple[int, int]]:
    if not intervals:
        return []

    # Validación: ningún intervalo puede tener inicio mayor que fin
    for start, end in intervals:
        if start > end:
            raise ValueError("El inicio de un intervalo no puede ser mayor que su fin")

    # Ordenamos una copia (no modificamos la entrada)
    sorted_intervals = sorted(intervals)

    # Fusión de intervalos que se solapan o se tocan
    merged = [sorted_intervals[0]]
    for start, end in sorted_intervals[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:  # se solapan o se tocan (cerrados)
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))

    return merged
```

